"""Pull every order listing page and the customer records for the spring reconciliation.

Raw JSON goes to /tmp/recon/raw (outside the workspace) so the compute step can be
re-run without calling the service again. Every retry is logged to /tmp/recon/fetch.log.
"""
import http.client
import json
import os
import time
import urllib.error
import urllib.request
from datetime import datetime, timezone
from email.utils import parsedate_to_datetime

BASE = "http://localhost:8080"
RAW = "/tmp/recon/raw"
LOG = "/tmp/recon/fetch.log"
MAX_ATTEMPTS = 40


def log(msg):
    line = f"{datetime.now(timezone.utc).strftime('%H:%M:%S')} {msg}"
    print(line, flush=True)
    with open(LOG, "a") as fh:
        fh.write(line + "\n")


def retry_after_seconds(headers, body):
    """Seconds the server asked us to wait, from a Retry-After header or a JSON body field."""
    value = headers.get("Retry-After") if headers is not None else None
    if value:
        try:
            return float(value)
        except ValueError:
            try:
                return max(0.0, (parsedate_to_datetime(value) - datetime.now(timezone.utc)).total_seconds())
            except (TypeError, ValueError):
                pass
    try:
        data = json.loads(body)
    except ValueError:
        return None
    if isinstance(data, dict):
        for key in ("retry_after", "retry_after_seconds", "retryAfter"):
            if key in data:
                try:
                    return float(data[key])
                except (TypeError, ValueError):
                    return None
    return None


class Api:
    def __init__(self):
        self.token = None
        self.counts = {}

    def _count(self, key):
        self.counts[key] = self.counts.get(key, 0) + 1

    @staticmethod
    def _raw(method, path, headers):
        req = urllib.request.Request(BASE + path, method=method, headers=headers)
        try:
            with urllib.request.urlopen(req, timeout=30) as resp:
                return resp.status, resp.headers, resp.read()
        except urllib.error.HTTPError as err:
            return err.code, err.headers, err.read()

    def _send(self, path):
        headers = {}
        if self.token is None:
            self._count("token_fetch")
            status, hdrs, body = self._raw("POST", "/token", {})
            if status != 200:
                return status, hdrs, body
            self.token = json.loads(body)["token"]
        headers["Authorization"] = f"Bearer {self.token}"
        return self._raw("GET", path, headers)

    def get(self, path):
        """GET an authenticated path and return its parsed JSON, or None on 404.

        Retries through token expiry (401), rate limiting (429/503), server errors and
        network faults. A failed request is repeated, never skipped; after MAX_ATTEMPTS
        it raises rather than returning partial data.
        """
        for attempt in range(1, MAX_ATTEMPTS + 1):
            try:
                status, hdrs, body = self._send(path)
            except (OSError, http.client.HTTPException, ValueError, KeyError) as exc:
                self._count("transport")
                log(f"{path} attempt {attempt}: transport error {exc!r}; retrying")
                time.sleep(min(2 ** attempt, 30))
                continue
            if status == 200:
                try:
                    return json.loads(body)
                except ValueError as exc:
                    self._count("bad_json")
                    log(f"{path} attempt {attempt}: 200 with unparseable body ({exc}); retrying")
                    time.sleep(min(2 ** attempt, 30))
                    continue
            if status == 404:
                return None
            if status == 401:
                self._count("401")
                log(f"{path} attempt {attempt}: 401 {body[:120]!r}; discarding token")
                self.token = None
                continue
            if status in (429, 503):
                self._count(str(status))
                delay = retry_after_seconds(hdrs, body)
                if delay is None:
                    delay = 2.0
                log(f"{path} attempt {attempt}: {status} {body[:200]!r}; waiting {delay:.2f}s")
                time.sleep(delay + 0.25)
                continue
            if status >= 500:
                self._count("5xx")
                log(f"{path} attempt {attempt}: {status} {body[:200]!r}; retrying")
                time.sleep(min(2 ** attempt, 30))
                continue
            raise RuntimeError(f"{path}: unexpected status {status} {body[:200]!r}")
        raise RuntimeError(f"{path}: still failing after {MAX_ATTEMPTS} attempts")


def fetch_orders(api):
    """Follow the documented 'next' links from page 1 to the end. Returns the page count."""
    page = 1
    total_pages = None
    path = "/orders?page=1"
    while path is not None:
        data = api.get(path)
        if data is None:
            raise RuntimeError(f"{path} returned 404")
        if data["page"] != page:
            raise RuntimeError(f"requested page {page}, server returned page {data['page']}")
        if total_pages is None:
            total_pages = data["total_pages"]
            log(f"server reports total_pages={total_pages}")
        if data["total_pages"] != total_pages:
            raise RuntimeError(f"total_pages changed mid-run: {total_pages} -> {data['total_pages']}")
        with open(os.path.join(RAW, f"orders-page-{page:03d}.json"), "w") as fh:
            json.dump(data, fh)
        log(f"page {page}/{total_pages}: {len(data['items'])} items")
        expected_next = f"/orders?page={page + 1}" if page < total_pages else None
        if data["next"] != expected_next:
            raise RuntimeError(f"page {page}: next={data['next']!r}, expected {expected_next!r}")
        path = data["next"]
        page += 1
    return page - 1


def fetch_customers(api, customer_ids):
    customers = {}
    missing = []
    for cid in sorted(customer_ids):
        rec = api.get(f"/customers/{cid}")
        if rec is None:
            missing.append(cid)
        else:
            customers[cid] = rec
    return customers, missing


def main():
    os.makedirs(RAW, exist_ok=True)
    api = Api()
    n_pages = fetch_orders(api)
    log(f"fetched {n_pages} order pages")

    customer_ids = set()
    for p in range(1, n_pages + 1):
        with open(os.path.join(RAW, f"orders-page-{p:03d}.json")) as fh:
            for item in json.load(fh)["items"]:
                customer_ids.add(item["customer_id"])
    log(f"distinct customer ids referenced by listing: {len(customer_ids)}")

    customers, missing = fetch_customers(api, customer_ids)
    with open(os.path.join(RAW, "customers.json"), "w") as fh:
        json.dump(customers, fh)
    with open(os.path.join(RAW, "customers-missing.json"), "w") as fh:
        json.dump(missing, fh)
    log(f"customers fetched: {len(customers)}; not found (404): {missing}")
    log(f"request counters: {api.counts}")


if __name__ == "__main__":
    main()

